"use client";

import { useEffect, useRef } from "react";
import { useLanguage } from "@/i18n/LanguageProvider";

/**
 * Official TradingView stock market heatmap embed.
 * No market data is scraped or generated by this site.
 * Leave the required provider attribution in place.
 * Reference: https://www.tradingview.com/widget-docs/widgets/heatmaps/stock-heatmap/
 */
export default function MarketHeatmap() {
  const host = useRef<HTMLDivElement>(null);
  const { language } = useLanguage();

  useEffect(() => {
    const element = host.current;
    if (!element) return;

    // TradingView's official embed expects a child div and its JSON config script.
    // Recreating the embed on a locale change avoids duplicated iframes.
    element.replaceChildren();
    const widget = document.createElement("div");
    widget.className = "tradingview-widget-container__widget";
    widget.style.height = "100%";
    widget.style.width = "100%";
    element.appendChild(widget);

    const script = document.createElement("script");
    script.type = "text/javascript";
    script.src = "https://s3.tradingview.com/external-embedding/embed-widget-stock-heatmap.js";
    script.async = true;
    script.textContent = JSON.stringify({
      dataSource: "SPX500",
      blockSize: "market_cap_basic",
      blockColor: "change",
      grouping: "sector",
      locale: language === "es" ? "es" : "en",
      colorTheme: "light",
      exchanges: [],
      hasTopBar: true,
      isDataSetEnabled: true,
      isZoomEnabled: true,
      hasSymbolTooltip: true,
      isMonoSize: false,
      symbolUrl: "",
      width: "100%",
      height: "100%",
    });
    element.appendChild(script);

    return () => { element.replaceChildren(); };
  }, [language]);

  return (
    <div className="overflow-hidden rounded-[24px] border border-black/[0.07] bg-[#f8fafb]">
      <div className="relative h-[420px] w-full sm:h-[520px] lg:h-[590px]">
        <div className="pointer-events-none absolute inset-0 flex items-center justify-center text-xs text-zinc-400">
          {language === "es" ? "Cargando mapa de mercado…" : "Loading market heatmap…"}
        </div>
        <div
          className="tradingview-widget-container relative z-10 h-full w-full"
          ref={host}
          aria-label={language === "es" ? "Mapa de calor del mercado bursátil" : "Stock market performance heatmap"}
        />
      </div>
      <div className="flex flex-wrap items-center justify-between gap-2 border-t border-black/[0.06] px-5 py-3 text-[11px] text-zinc-400">
        <span>{language === "es" ? "S&P 500 · Variación diaria por sector" : "S&P 500 · Daily performance by sector"}</span>
        <a
          className="text-cyan-700 hover:underline"
          href="https://www.tradingview.com/heatmap/stock/"
          target="_blank"
          rel="noopener noreferrer nofollow"
        >
          {language === "es" ? "Mapa de calor por TradingView ↗" : "Stock heatmap by TradingView ↗"}
        </a>
      </div>
    </div>
  );
}
